import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            for (int test = 1; ; test++) {
                int n = in.nextInt();
                int D = in.nextInt();
                if (n == 0 && D == 0) {
                    break;
                }
                out.println("@" + test);
                final double r = 1;
                Point pl = new Point(-D, 0);
                Point pr = new Point(+D, 0);
                for (int i = 0; i < n; i++) {
                    int sl = in.nextInt();
                    int sr = in.nextInt();
                    double vl = sl / 180.0 * Math.PI * r;
                    double vr = sr / 180.0 * Math.PI * r;
                    int t = in.nextInt();
                    if (sl == sr) {
                        Point v = pr.sub(pl).rotate(Math.PI / 2).norm().scale((vl + vr) * 0.5 * t);
                        pl = pl.add(v);
                        pr = pr.add(v);
                        continue;
                    }
                    double x = D * (vl + vr) / (vl - vr);
//                double x = D * (vl + vr) / (vr - vl);
                    Point o = pl.add(pr).scale(0.5);
                    Point ox = o.add(pr.sub(o).norm().scale(x));
//                out.println("!" + cross(ox,pr.sub(pl)));

                    Point nl = pl.sub(ox);
                    Point nr = pr.sub(ox);
//                nl=nl.scale(-1);
//                nr=nr.scale(-1);
                    double wl = vl / nl.length();
                    double wr = vr / nr.length();
//                if (x < D && x > -D) {
//                    wr = -wr;
//                }
//                out.println(wl + " " + wr);
                    nl = nl.rotate(wl * t);
                    nr = nr.rotate(wr * t);

                    pl = nl.add(ox);
                    pr = nr.add(ox);
                }
                Point p = pl.add(pr).scale(0.5);
                out.printf("%.10f\n", p.x);
                out.printf("%.10f\n", p.y);
            }
        }

        class Point {
            double x;
            double y;

            Point(double x, double y) {
                this.x = x;
                this.y = y;
            }

            Point add(Point o) {
                return new Point(x + o.x, y + o.y);
            }

            Point sub(Point o) {
                return new Point(x - o.x, y - o.y);
            }

            Point rotate(double alpha) {
                double c = Math.cos(alpha);
                double s = Math.sin(alpha);
                double nx = x * c - y * s;
                double ny = x * s + y * c;
                return new Point(nx, ny);
            }

            Point norm() {
                double len = length();
                return scale(1.0 / len);
            }

            Point scale(double f) {
                return new Point(f * x, f * y);
            }

            double length() {
                return Math.sqrt(x * x + y * y);
            }

            public String toString() {
                return String.format("%.2f %.2f", x, y);
            }

        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}


